def find_extremes(numbers):
    """
    Finds the largest negative number and the smallest positive number in a list.

    Args:
        numbers (list): A list of numbers (integers or floats).

    Returns:
        dict: A dictionary containing 'largest_negative' and 'smallest_positive'.
              Returns None for a value if it does not exist in the list.
    """
    largest_negative = None
    smallest_positive = None

    for num in numbers:
        if num < 0:
            if largest_negative is None or num > largest_negative:
                largest_negative = num
        elif num > 0:
            if smallest_positive is None or num < smallest_positive:
                smallest_positive = num

    return {
        'largest_negative': largest_negative,
        'smallest_positive': smallest_positive
    }

