from itertools import chain

def intersperse(delimiter, numbers):
    """Insert *delimiter* between each pair of consecutive integers in *numbers*."""
    # `chain.from_iterable` expands each element into a sequence.
    # For each number except the last we add the delimiter after it.
    return list(chain.from_iterable(
        (n, delimiter) if i < len(numbers) - 1 else (n,)
        for i, n in enumerate(numbers)
    ))

# Example usage:
if __name__ == "__main__":
