import sys

def get_prime_factors(n):
    """Returns a list of prime factors of n (including repetitions)."""
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def is_product_of_three_primes(n):
    """Checks if n is a product of exactly three prime numbers (not necessarily distinct)."""
    if n < 2:
        return False

    factors = get_prime_factors(n)
    return len(factors) == 3

